const NormalFrameTarget &named_target(const NormalFrames &r,uint64_t id){for(const auto &t:r.targets)if(t.id==id)return t;throw std::runtime_error("Missing actual named artist target");}
bool near_direction(Vec3 a,Vec3 b){return length(a-b)<1e-6f;}
void ready_relative(Document &doc){if(!doc.wait_asset(std::chrono::seconds(120))||!doc.wait_mesh(std::chrono::seconds(120))||!doc.frame().state->error.empty())throw std::runtime_error(doc.frame().state->error);}
void native_oracle(const Scene &scene){
 const auto &node=*scene.active().material_bindings->key_derivation;check(node.uses_explicit_mirror()&&node.before_paint()->mesh().positions.size()==12,"Native consumer owns true independent current12 with real conversion anchor");const auto selected=node.targets().back();constexpr uint32_t opposite[]={0,2,1,9,11,10,6,8,7,3,5,4};const auto id=scene.active().material_bindings->normal_frames->current_targets.back();
 for(bool toon:{false,true}){const auto before=toon?node.before_material()->normal_frames->mtoon:node.before_material()->normal_frames->pbr,after=toon?scene.active().material_bindings->normal_frames->mtoon:scene.active().material_bindings->normal_frames->pbr;const auto &a=named_target(*before,*selected.reference),&b=named_target(*after,id);for(size_t c=0;c<12;++c){const auto n=a.normals[opposite[c]],t=a.tangents[opposite[c]];Vec3 en{-n.x,n.y,n.z},et{t.x,-t.y,-t.z};if(c/3==3){en=toon?Vec3{n.z,-n.y,-n.x}:Vec3{-n.x,n.z,-n.y};et=toon?Vec3{-t.z,t.y,t.x}:Vec3{t.x,-t.z,t.y};}if(c/3==1){en=toon?Vec3{-n.z,-n.y,n.x}:Vec3{-n.x,-n.z,n.y};et=toon?Vec3{t.z,t.y,-t.x}:Vec3{t.x,t.z,-t.y};}check(near_direction(en,b.normals[c])&&near_direction(et,b.tangents[c]),"Independent per-corner signed-axis oracle retains both latent actual artist channels");}}
}
size_t strongest_target(const SculptObject&o){
 if(!o.deformation||!o.deformation->morphs||!o.material_bindings||!o.material_bindings->normal_frames)throw std::runtime_error("Missing genuine avatar morph source");double best=-1;size_t at=0;const auto &set=*o.material_bindings->normal_frames;
 for(size_t i=0;i<o.deformation->morphs->targets.size();++i){double score=0;for(auto v:o.deformation->morphs->targets[i].delta)score+=double(dot(v,v));for(const auto &role:{set.pbr,set.mtoon})if(role){const auto &t=named_target(*role,set.current_targets.at(i));for(auto v:t.normals)score+=double(dot(v,v));for(auto v:t.tangents)score+=double(dot(v,v));}if(score>best){best=score;at=i;}}
 check(best>0,"Actual avatar selected source has real nonzero POSITION or artist-direction data");std::cout<<"SOURCE_TARGET "<<at<<" name="<<o.deformation->morphs->targets[at].name<<" score="<<best<<std::endl;return at;
}
Scene authored_avatar(Scene source,double plane,bool controlled){
 const auto group=source.active().group;if(!group)throw std::runtime_error("Actual avatar part lost its source group");source.group(group).transform.scale=.8f;source.group(group).transform.position.y=-.7f;
 // These are explicit native authored fixtures BEFORE Mirror, never exporter
 // snapshot rewrites. The default all-role case below remains independent.
 if(controlled)controlled_lighting(source,group);
 if(!std::getenv("DOME_RELATIVE_DEFAULT_UNLIT"))for(const auto &o:source.objects())if(o.group==group)source.object(o.id).material.unlit=false;
 if(std::getenv("DOME_RELATIVE_BEFORE_KEY")){std::cout<<"BEFORE_KEY_CONTROL "<<source.active().name<<std::endl;return source;}
 const auto before=source.encode();ShapeKeyEdit edit;edit.action=ShapeKeyAction::Mirror;edit.target=strongest_target(source.active());edit.name="Source-plane converted real artist Mirror";edit.mirror_plane=plane;edit.mirror_frames=ShapeKeyMirrorFrames::BaseRelative;const auto artist=source.active().material_bindings->normal_frames;author_shapekey(source,source.active().id,edit);check(source.active().material_bindings->key_derivation->before_material()->normal_frames==artist,"Actual avatar conversion retains all original artist target arrays and owning roles");
 // A genuine subsequent native edit makes this a sculpted key as well as a
 // named reflected seed. It uses actual role UVs and keeps the fixed anchor.
 const auto anchor=source.active().material_bindings->key_derivation->before_material();edit.action=ShapeKeyAction::Replace;edit.target=source.active().deformation->morphs->targets.size()-1;edit.positions=source.active().painted->mesh().positions;for(size_t v=0;v<edit.positions.size();++v){const auto p=edit.positions[v];edit.positions[v]+=source.active().deformation->morphs->targets.back().delta[v];edit.positions[v].z+=.0015f*std::sin(p.x*130.f)*std::cos(p.y*110.f);}author_shapekey(source,source.active().id,edit);check(source.active().material_bindings->key_derivation->before_material()==anchor,"Real post-Mirror sculpt endpoint retains its immutable named-operation anchor");check(Scene::decode(source.encode()).encode()==source.encode(),"Actual avatar converted/sculpted key graph survives owning codec restart");return source;
}
void avatar_pose(Scene &s,int mode,float weight){const auto group=s.active().group,active=s.active().id;for(const auto &o:s.objects())if(o.group==group&&o.deformation){auto d=*o.deformation;d.pose.clear();for(const auto &bone:d.skeleton->bones)d.pose.push_back(bone.rest);if(mode&&d.humanoid){const auto hips=d.humanoid->joints.at("hips"),spine=d.humanoid->joints.at("spine");d.pose[hips].scale={1.15f,.9f,.7f};d.pose[spine].scale={.85f,1.05f,1.2f};if(mode==2)d.pose[spine].rotation=Quat{std::cos(.08f),0,0,std::sin(.08f)};}if(d.morphs){d.morph_weights.assign(d.morphs->targets.size(),0);if(o.id==active){d.morph_weights[0]=.2f;d.morph_weights.back()=weight;}}s.set_deformation(o.id,std::move(d));}}
void avatar_consumer(Scene source,const std::filesystem::path &out,bool vrm,SurfaceRenderer &renderer,Fbo&fbo,frame_consumer::Renderer &consumer){
 std::filesystem::create_directories(out);source.save(out/"source.dsculpt");source=Scene::load(out/"source.dsculpt");const auto immutable=source.encode();Pixels zero;for(int pose=0;pose<3;++pose)for(float weight:{0.f,.35f,1.f}){if(std::getenv("DOME_RELATIVE_BEFORE_KEY")&&(pose||weight!=0))continue;auto current=source;avatar_pose(current,pose,weight);Document doc;doc.replace(current);ready_relative(doc);if(!vrm){doc.shading(false);ready_relative(doc);}const auto expected=doc.copy_scene().encode();const auto snapshot=doc.frame().surface;check(snapshot&&snapshot->pbr_view==!vrm&&doc.frame().state->pbr_view==!vrm&&snapshot->view_epoch==doc.frame().state->view_epoch,"Actual rendered endpoint publishes the requested matching frame-role epoch");for(const auto &range:snapshot->ranges)check(range.pbr_view==!vrm,"Every actual rendered range owns the captured requested role");std::cout<<"VIEW_EPOCH "<<snapshot->view_epoch<<" pbr="<<snapshot->pbr_view<<" ranges="<<snapshot->ranges.size()<<std::endl;const auto native=key_draw(renderer,snapshot);const auto uploads=renderer.buffer_stats();const auto images=renderer.texture_stats();check(native==key_draw(renderer,snapshot)&&renderer.buffer_stats().geometry_uploads==uploads.geometry_uploads&&renderer.texture_stats().uploads==images.uploads,"Actual converted avatar second eye/noop reuses geometry and images");const auto path=out/("p"+std::to_string(pose)+"-w"+std::to_string(int(weight*100))+(vrm?".vrm":".glb"));doc.export_asset(path,vrm?AssetExportFormat::Avatar:AssetExportFormat::Glb).get();frame_consumer::Model model(path);const nlohmann::json *metadata=vrm?&model.json.at("extensions").at("VRM"):nullptr;Quat basis{};if(vrm){const auto surfaces=current.preview_surfaces();for(const auto &part:surfaces)if(part.appearance&&part.appearance->source_basis_quaternion){basis=*part.appearance->source_basis_quaternion;break;}}fbo.bind();consumer.render(model.data,metadata,basis,true);const auto external=read();const auto error=delta(native,external);size_t covered=0;for(size_t i=3;i<external.size();i+=4)covered+=external[i]>0;std::cout<<"RELATIVE_AVATAR "<<(vrm?"VRM":"GLB")<<" pose="<<pose<<" weight="<<weight<<" error="<<error<<" covered="<<covered<<std::endl;check(covered>300&&error<=4,"Independent actual converted/sculpted avatar pixels preserve declared role transport across poses and morphs");if(!pose&&weight==0)zero=native;if(!pose&&weight==1){const auto change=delta(zero,native);std::cout<<"RELATIVE_AVATAR_SENSITIVITY "<<change<<std::endl;check(change>2,"Genuine converted and sculpted avatar target makes visible pixel changes");}check(doc.copy_scene().encode()==expected,"Actual authored/PBR commands and export preserve all material and source owners");}check(source.encode()==immutable,"Independent avatar consumer leaves complete saved source unchanged");
}
