 if(argc<5||argc>6||(argc==6&&std::string_view(argv[5])!="--hardware"))return 2;const bool hardware=argc==6;const std::filesystem::path out=argv[1];NativeGraphics graphics;const std::string vendor=reinterpret_cast<const char*>(glGetString(GL_VENDOR)),device=reinterpret_cast<const char*>(glGetString(GL_RENDERER));std::cout<<"GL_VENDOR "<<vendor<<"\nGL_RENDERER "<<device<<std::endl;const bool software=device.find("llvmpipe")!=std::string::npos||device.find("softpipe")!=std::string::npos;check(hardware?(vendor.find("Intel")!=std::string::npos&&device.find("Arc")!=std::string::npos&&device.find("A770")!=std::string::npos&&device.find("UHD")==std::string::npos&&!software):software,"Relative key consumers use the explicitly requested graphics device");Fbo fbo;fbo.bind();SurfaceRenderer renderer;frame_consumer::Renderer consumer;
